class KMAE_Icons {

	/**
	 * @param string               $name Icon slug.
	 * @param array<string, mixed> $args size, class.
	 */
	public static function render( $name, $args = array() ) {
		$aliases = array(
			'chat'      => 'message-square',
			'gear'      => 'settings',
			'lightning' => 'zap',
		);
		if ( isset( $aliases[ $name ] ) ) {
			$name = $aliases[ $name ];
		}

		$paths = self::paths();
		if ( ! isset( $paths[ $name ] ) ) {
			return '';
		}

		$size  = isset( $args['size'] ) ? (int) $args['size'] : 20;
		$class = isset( $args['class'] ) ? $args['class'] : '';

		return sprintf(
			'<svg xmlns="http://www.w3.org/2000/svg" width="%1$d" height="%1$d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" class="kmae-icon kmae-icon-%2$s %3$s" aria-hidden="true" focusable="false">%4$s</svg>',
			$size,
			esc_attr( $name ),
			esc_attr( $class ),
			$paths[ $name ]
		);
	}

